window.ATLAS_ITEMS=window.ATLAS_ITEMS||{};window.ATLAS_ITEMS[78]={"id":"078","numero":78,"titre":"Addiction aux drogues (cannabis, cocaïne, amphétamines, opiacés)","objectifs":[{"id":"78-1","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","contenu":"<p>Cet item regroupe l'addiction au <strong>cannabis</strong>, à la <strong>cocaïne</strong>, aux <strong>amphétamines</strong>, aux <strong><span class=\"kw-ttt\">opiacés</span></strong> et aux <strong>drogues de synthèse</strong>. Chaque famille se définit d'abord par son origine et sa nature.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Définition / origine</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cannabis</span></td><td>Substance issue de la plante <em>Cannabis sativa</em> ; substance illicite la plus consommée en France</td></tr>\n          <tr><td><span class=\"kw-def\">Cocaïne</span></td><td>Substance stimulante extraite des feuilles de <strong>coca</strong> (cultivées principalement en Amérique du Sud)</td></tr>\n          <tr><td><span class=\"kw-def\">Amphétamines</span></td><td>Dérivés amphétaminiques de synthèse : amphétamine, MDMA/ecstasy, méthamphétamine</td></tr>\n          <tr><td><span class=\"kw-def\">Opiacés</span></td><td>Substances dérivées du <strong>pavot</strong> : naturelles (<span class=\"kw-ttt\">morphine</span>), semi-synthétiques (héroïne), ou de synthèse à action morphinique</td></tr>\n          <tr><td><span class=\"kw-def\">Drogues de synthèse</span></td><td>Nouveaux produits de synthèse (<span class=\"kw-def\">NPS</span> / NSP) : substances récentes, fabriquées en Asie et en Europe, longtemps non contrôlées ni réglementées</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Notion clé — le mésusage.</strong> Pour ces substances illicites, <strong>tout usage est considéré comme un mésusage</strong> : soit un <span class=\"kw-def\">usage à risque</span> (en l'absence de trouble addictologique constitué), soit une <span class=\"kw-def\">dépendance</span>. Il n'existe <strong>pas de dose seuil</strong> connue en dessous de laquelle le risque serait nul.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 75 — Addiction <span class=\"kw-etio\">Tabac</span> · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 77 — Addiction aux psychotropes</em></p>","frequence":0},{"id":"78-2","rang":"A","rubrique":"Définition","titre":"Connaître les principes actifs","contenu":"<p>Le <strong>principe actif</strong> est la molécule responsable des effets psychoactifs ; il varie selon la famille.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Principe(s) actif(s)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cannabis</span></td><td>\n            <strong><span class=\"kw-def\">Δ9-THC</span></strong> (delta-9-tétrahydrocannabinol) : principe psychoactif, <span class=\"kw-clinique\">agoniste</span> des récepteurs cannabinoïdes <strong>CB1</strong> et <strong>CB2</strong><br>\n            <strong>CBD</strong> (<span class=\"kw-def\">cannabidiol</span>) : antagoniste de CB1, agoniste de CB2<br>\n            Les cannabinoïdes peuvent aussi être <strong>synthétisés</strong> (e-liquide, spice, k2)\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Cocaïne</span></td><td>\n            <strong>Chlorhydrate de cocaïne</strong> : forme poudre blanche<br>\n            <strong>Cocaïne base</strong> : crack (adjonction de bicarbonate de soude) ou free base (ammoniaque)\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Amphétamines</span></td><td>\n            Amphétamine ; <strong>MDMA</strong> (ecstasy) ; <strong>méthamphétamine</strong> — effets particulièrement puissants, durables, fort potentiel addictif\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Opiacés</span></td><td>\n            <strong>Naturels :</strong> <span class=\"kw-ttt\">morphine</span><br>\n            <strong>Semi-synthétiques :</strong> héroïne (diacétylmorphine)<br>\n            <strong>Synthétiques à action morphinique :</strong> <span class=\"kw-ttt\">tramadol</span> ; <span class=\"kw-ttt\">codéine</span> ; buprénorphine ; méthadone ; <span class=\"kw-ttt\">oxycodone</span> ; <span class=\"kw-ttt\">fentanyl</span>\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Drogues de synthèse</span></td><td>\n            <strong>Cannabinoïdes de synthèse</strong> (Spice…) — effet hallucinogène<br>\n            <strong>Cathinones de synthèse</strong> (méphédrone, MDPV, méthylone, 3-MMC, 4-MEC) — effet psychostimulant\n          </td></tr>\n          <tr><td>Hallucinogènes / GHB / <span class=\"kw-ttt\">kétamine</span></td><td>\n            LSD (diéthylamide de l'acide lysergique) ; champignons hallucinogènes ; GHB / GBL ; <span class=\"kw-ttt\">kétamine</span>\n          </td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"78-3","rang":"A","rubrique":"Définition","titre":"Connaître les modes de consommation et leurs effets","contenu":"<p>Les drogues se classent en <strong>trois grandes catégories selon leur effet</strong> sur le système nerveux central — c'est la grille de lecture fondamentale de l'item.</p>\n      <table >\n        <thead><tr><th>Classe</th><th>Effets</th><th>Exemples</th><th>Risque principal</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Perturbateurs / hallucinogènes</span></td>\n            <td><span class=\"kw-clinique\">Désorientation</span> temporo-spatiale ; altération des perceptions sensorielles ; distorsion de la réalité, <span class=\"kw-clinique\">hallucinations</span></td>\n            <td>Cannabis ; champignons hallucinogènes ; <span class=\"kw-ttt\">kétamine</span> ; LSD ; MDMA/ecstasy ; PCP</td>\n            <td><span class=\"kw-alerte\">Troubles psychiatriques</span> : bad trips, dépersonnalisation, psychoses</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Dépresseurs</span></td>\n            <td>Ralentissement cérébral et moteur ; baisse de la vigilance et des réflexes ; effet anxiolytique, parfois euphorique</td>\n            <td><span class=\"kw-etio\">Alcool</span> ; GHB ; héroïne</td>\n            <td><span class=\"kw-alerte\">Dépression respiratoire</span> ; forte dépendance ; risque d'overdose</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Stimulants</span></td>\n            <td>Excitation, agitation, hausse de l'énergie ; accélération du rythme cardiaque ; effet euphorisant et désinhibant</td>\n            <td>Amphétamines ; cocaïne ; méthamphétamine</td>\n            <td><span class=\"kw-alerte\">Hyperstimulation cardiaque et cérébrale</span> : <span class=\"kw-etio\">IDM</span>, <span class=\"kw-etio\">AVC</span>, psychoses (paranoïa)</td>\n          </tr>\n        </tbody>\n      </table>\n      <p><strong>Modes de consommation</strong> selon les substances : <span class=\"kw-clinique\">fumé</span> (joint, pipe à eau) ; <span class=\"kw-clinique\">ingéré</span> (space cake, comprimé) ; <span class=\"kw-clinique\">sniffé</span> par voie intranasale ; <span class=\"kw-clinique\">injecté</span> par voie intraveineuse ; <span class=\"kw-clinique\">inhalé</span> ou vaporisé.</p>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Le mélange de substances de classes différentes augmente fortement le risque de toxicité et d'overdose.</div>","frequence":0},{"id":"78-4","rang":"A","rubrique":"Définition","titre":"Connaître les voies d’administration","contenu":"<p>La <strong>voie d'administration</strong> conditionne la rapidité d'apparition et la durée des effets : plus l'absorption est rapide (inhalation, voie IV), plus l'effet est intense, bref et addictogène.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Voies d'administration</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cannabis</span></td><td>\n            <strong>Fumé</strong> +++ : joint (mélangé au <span class=\"kw-etio\">tabac</span>), pipe à eau (bang)<br>\n            <strong>Ingéré :</strong> space cake (plus rare)<br>\n            <strong>Vaporisé</strong> ou consommé en cigarette électronique (cannabinoïdes de synthèse)\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Cocaïne</span></td><td>\n            <strong>Poudre :</strong> voie intranasale (sniff) ou voie intraveineuse (slam, shoot)<br>\n            <strong>Base (crack / free base) :</strong> inhalée (fumée), plus rarement injectée<br>\n            <strong>Non ingérée</strong> (mauvaise biodisponibilité), sauf prise involontaire\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Amphétamines</span></td><td>\n            MDMA : poudre sniffée par voie intranasale, injectée, ou comprimé avalé (« gober »)\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Opiacés</span> (héroïne)</td><td>\n            Voie nasale (sniff) ; fumée ; voie intraveineuse (shoot, fix)\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Cathinones de synthèse</span></td><td>\n            Voies multiples : orale (drop), inhalée, intranasale, IV (slam), intrarectale (plug)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège — la voie injectable.</strong> La voie intraveineuse et le <span class=\"kw-alerte\">slam</span> (injection en contexte sexuel) exposent au risque infectieux majeur : <span class=\"kw-alerte\">VIH, VHB, VHC</span>, abcès, <span class=\"kw-etio\">endocardite</span> (voir « Principales complications »).</div>","frequence":0},{"id":"78-5","rang":"B","rubrique":"Définition","titre":"Connaître la prévalence de l’utilisation des principales drogues psychoactives","contenu":"<p>Données épidémiologiques françaises pour les principales drogues psychoactives.</p>\n      <table >\n        <thead><tr><th>Substance</th><th>Expérimentation</th><th>Usage régulier / actuel</th><th>Repères</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cannabis</span></td>\n            <td><span class=\"kw-chiffre\">47 %</span> ; <span class=\"kw-chiffre\">30 %</span> des jeunes de <span class=\"kw-chiffre\">18 ans</span></td>\n            <td>Usagers réguliers <span class=\"kw-chiffre\">3 %</span></td>\n            <td><strong>Substance illicite la plus consommée en France</strong> (<span class=\"kw-chiffre\">18-64 ans</span>) ; usage à risque <span class=\"kw-chiffre\">3 %</span> des <span class=\"kw-chiffre\">18-64 ans</span> et <span class=\"kw-chiffre\">7 %</span> des <span class=\"kw-chiffre\">17 ans</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Cocaïne</span></td>\n            <td><span class=\"kw-chiffre\">5,5 %</span></td>\n            <td>Usage régulier <span class=\"kw-chiffre\">1,5 %</span></td>\n            <td><strong>2ᵉ substance illicite</strong> en France ; ≈ <span class=\"kw-chiffre\">400 000</span> personnes avec un problème de consommation</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Amphétamines</span></td>\n            <td>Amphétamine <span class=\"kw-chiffre\">2,2 %</span> ; MDMA/ecstasy <span class=\"kw-chiffre\">5 %</span></td>\n            <td>MDMA/ecstasy : usagers actuels <span class=\"kw-chiffre\">1 %</span></td>\n            <td>Méthamphétamine <strong>très peu consommée</strong> en France</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Opiacés</span> (héroïne)</td>\n            <td><span class=\"kw-chiffre\">1,3 %</span> ; <span class=\"kw-chiffre\">0,7 %</span> des jeunes de <span class=\"kw-chiffre\">17 ans</span></td>\n            <td>Usage actuel <span class=\"kw-chiffre\">0,2 %</span></td>\n            <td>≈ <span class=\"kw-chiffre\">180 000</span> personnes sous traitement de substitution aux <span class=\"kw-ttt\">opioïdes</span></td>\n          </tr>\n        </tbody>\n      </table>","frequence":0},{"id":"78-6","rang":"A","rubrique":"Définition","titre":"Connaître la définition de l’intoxication aiguë","contenu":"<p>L'<strong><span class=\"kw-def\">intoxication aiguë</span></strong> est l'ensemble des manifestations cliniques <strong>transitoires</strong> liées à la prise récente d'une substance psychoactive. Les effets sont <strong>dose-, voie- et individu-dépendants</strong>.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Cinétique</th><th>Tableau clinique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cannabis</span><br>(ivresse cannabique)</td>\n            <td>Début <span class=\"kw-chiffre\">15-20 min</span> si fumé (plusieurs heures si ingéré) ; durée <span class=\"kw-chiffre\">3-6 h</span></td>\n            <td>\n              <strong>Psychique :</strong> euphorie, désinhibition, hyperphagie ; troubles du jugement, idées de référence (« <span class=\"kw-clinique\">effet parano</span> ») ; troubles cognitifs (mémoire, attention) ; distorsion du temps et de l'espace ; <span class=\"kw-clinique\">hallucinations</span> possibles<br>\n              <strong>Physique :</strong> <span class=\"kw-def\">HTA</span>, <span class=\"kw-clinique\">tachycardie</span> ; hyperhémie conjonctivale, <span class=\"kw-clinique\">mydriase bilatérale</span> ; bouche sèche\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Cocaïne</span> et <span class=\"kw-def\">amphétamines</span></td>\n            <td>Cocaïne base <span class=\"kw-chiffre\">1-2 min</span> / poudre <span class=\"kw-chiffre\">15-30 min</span> ; « descente » sur quelques minutes à heures</td>\n            <td>\n              <strong>1ʳᵉ phase :</strong> <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-def\">HTA</span>, <span class=\"kw-clinique\">mydriase</span>, <span class=\"kw-clinique\">pâleur</span> cutanée + symptomatologie <span class=\"kw-clinique\">maniaque</span> (euphorie, tachypsychie, hypervigilance, <span class=\"kw-clinique\">anorexie</span>, insomnie)<br>\n              <strong>2ᵉ phase — « descente » :</strong> dysphorie, <span class=\"kw-clinique\">asthénie</span>, irritabilité, anxiété, <span class=\"kw-clinique\">craving</span><br>\n              <strong>Amphétamines, forte dose :</strong> crises d'angoisse, <span class=\"kw-clinique\">convulsions</span>, <span class=\"kw-alerte\">hyperthermie maligne = syndrome sérotoninergique</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Opiacés</span><br>(toxidrome morphinique)</td>\n            <td>Variable selon la molécule ; danger principal = <span class=\"kw-def\">dépression</span> respiratoire</td>\n            <td>\n              <strong>Triade caractéristique :</strong> troubles de conscience (<span class=\"kw-clinique\">coma calme</span>, hypotonique, aréflexique) ; <span class=\"kw-clinique\">myosis serré bilatéral</span> ; <span class=\"kw-alerte\">détresse respiratoire</span> (<span class=\"kw-clinique\">bradypnée</span> ≤ <span class=\"kw-chiffre\">10/min</span>, respiration de Cheyne-Stokes)<br>\n              <strong>Autres :</strong> globe urinaire, <span class=\"kw-clinique\">hypothermie</span>, troubles du rythme, hypotension\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">GHB / GBL</span> et <span class=\"kw-def\">kétamine</span></td>\n            <td>GHB : effet à <span class=\"kw-chiffre\">15 min</span>, durée <span class=\"kw-chiffre\">3-4 h</span> · <span class=\"kw-ttt\">kétamine</span> : durée <span class=\"kw-chiffre\">2-4 h</span></td>\n            <td>\n              <strong>GHB/GBL :</strong> euphorie, désinhibition, effet aphrodisiaque, altération de la conscience ; overdose = « <span class=\"kw-alerte\">G-Hole</span> » (<span class=\"kw-clinique\">bradypnée</span>, apnée, <span class=\"kw-clinique\">coma</span>)<br>\n              <strong>Kétamine :</strong> dépersonnalisation, déréalisation, « <span class=\"kw-alerte\">K-hole</span> » ; <span class=\"kw-def\">dépression</span> respiratoire, <span class=\"kw-clinique\">coma</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Hallucinogènes</span> (LSD, champignons)</td>\n            <td>Effet dose- et individu-dépendant</td>\n            <td>Hallucinations, distorsions perceptuelles, agitation ; <span class=\"kw-clinique\">mydriase</span>, nystagmus ; <span class=\"kw-clinique\">hyperthermie</span>, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-def\">HTA</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Discriminant pupillaire.</strong> Intoxication aux <strong><span class=\"kw-ttt\">opiacés</span></strong> → <span class=\"kw-clinique\">myosis</span> serré. Intoxication aux <strong>stimulants, au cannabis, aux hallucinogènes</strong> → <span class=\"kw-clinique\">mydriase</span>.</div>","frequence":0},{"id":"78-7","rang":"A","rubrique":"Définition","titre":"Connaître les comorbidités psychiatriques et addictives","contenu":"<p>Il faut distinguer la <strong>comorbidité</strong> (trouble préexistant ou durablement associé à l'addiction) de la <strong>complication</strong> (trouble <em>induit</em> par la consommation — voir « Principales complications »).</p>\n      <table >\n        <thead><tr><th>Type</th><th>Comorbidités fréquemment associées</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Psychiatriques</span></td>\n            <td>\n              <strong><span class=\"kw-etio\">Schizophrénie</span> :</strong> chez le sujet vulnérable, le cannabis peut <span class=\"kw-alerte\">précipiter l'entrée dans la maladie</span> et aggraver son évolution<br>\n              <strong><span class=\"kw-etio\">Trouble bipolaire</span> :</strong> aggravé par le cannabis (épisodes maniaques, cycles rapides)<br>\n              <strong>Troubles de la personnalité :</strong> antisociale, borderline<br>\n              <strong>État de stress post-traumatique</strong><br>\n              <strong>Troubles anxieux</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Addictives</span></td>\n            <td>\n              Association à d'autres addictions aux <strong>substances psychoactives</strong> : <span class=\"kw-etio\">alcool</span>, cocaïne, <span class=\"kw-ttt\">benzodiazépines</span>, <span class=\"kw-etio\">tabac</span><br>\n              Addictions <strong>comportementales</strong>\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Toute addiction impose la recherche systématique d'une <strong>comorbidité psychiatrique</strong> et d'une <strong>polyconsommation</strong> — elles aggravent le pronostic et conditionnent la prise en charge.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 63 — Trouble schizophrénique · 64 — <span class=\"kw-etio\">Trouble bipolaire</span> · 66 — Trouble dépressif · 76 — Addiction à l'<span class=\"kw-etio\">alcool</span> · 77 — Addiction aux psychotropes</em></p>","frequence":0},{"id":"78-8","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un syndrome d’intoxication chronique","contenu":"<p>Le <strong><span class=\"kw-def\">syndrome d'intoxication chronique</span></strong> regroupe les manifestations durables liées à une consommation répétée et prolongée.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Manifestations de l'intoxication chronique</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cannabis</span></td>\n            <td>\n              <strong>Altération des performances cognitives :</strong> troubles de la <span class=\"kw-clinique\">mémoire</span> ; atteinte des fonctions exécutives (décision, inhibition) ; difficultés <span class=\"kw-clinique\">attentionnelles</span><br>\n              <strong>Syndrome amotivationnel</strong> = indifférence affective + désinvestissement des relations sociales + baisse des performances scolaires ou professionnelles\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Cocaïne</span></td>\n            <td>\n              Altération des capacités <span class=\"kw-clinique\">attentionnelles</span> et <span class=\"kw-clinique\">mnésiques</span> ; atteinte des fonctions exécutives<br>\n              <span class=\"kw-radio\">Atrophie</span> possible des régions <strong>préfrontales</strong> et <strong>temporales</strong>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Amphétamines</span></td>\n            <td>\n              <strong>Signes généraux :</strong> <span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">perte de poids</span> (effet anorexigène) ; troubles du sommeil<br>\n              <strong>Psychiatriques :</strong> anxiété, troubles de l'humeur, symptômes psychotiques transitoires<br>\n              <strong>Autres organes :</strong> atteinte rénale, digestive et hépatique ; <span class=\"kw-alerte\">œdème pulmonaire</span> ; troubles du rythme cardiaque ; sécheresse buccale\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Mot-clé EDN.</strong> Le <strong>syndrome amotivationnel</strong> du cannabis (indifférence affective, désinvestissement social, chute des performances) est une notion classiquement tombable.</div>","frequence":0},{"id":"78-9","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un syndrome de sevrage","contenu":"<p>Le <strong><span class=\"kw-def\">syndrome de sevrage</span></strong> survient à l'arrêt ou à la réduction d'une consommation, et témoigne d'une <strong>dépendance physique</strong>.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Délai / durée</th><th>Manifestations</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cannabis</span></td>\n            <td>Apparition en <span class=\"kw-chiffre\">24-72 h</span> ; maximal la 1ʳᵉ semaine ; durée <span class=\"kw-chiffre\">1-3 semaines</span> (sommeil jusqu'à <span class=\"kw-chiffre\">1 mois</span>) ; concerne <span class=\"kw-chiffre\">10-40 %</span> des usagers</td>\n            <td>Irritabilité, humeur triste, agressivité, anxiété, nervosité ; troubles du sommeil (insomnie, cauchemars) ; baisse de l'appétit ; signes physiques : <span class=\"kw-clinique\">douleurs abdominales</span>, tremblements, sudation, <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">céphalées</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Cocaïne</span></td>\n            <td>Quelques heures après l'arrêt ; durée plusieurs semaines</td>\n            <td>Tableau <strong>pseudo-dépressif</strong> : humeur dysphorique ; ralentissement psychomoteur ou agitation ; <span class=\"kw-clinique\">asthénie</span> ; <span class=\"kw-clinique\">hypersomnie</span> ; augmentation de l'appétit</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Amphétamines</span></td>\n            <td>Quelques jours après l'arrêt ; durée <span class=\"kw-chiffre\">1-2 semaines</span></td>\n            <td>Dysphorie, anxiété, <span class=\"kw-def\">dépression</span> avec anhédonie → <span class=\"kw-alerte\">risque suicidaire</span> ; <span class=\"kw-clinique\">asthénie</span> intense ; augmentation de l'appétit ; troubles du sommeil et de la concentration</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Opiacés</span></td>\n            <td>Héroïne : <span class=\"kw-chiffre\">6-12 h</span> après la dernière prise, durée <span class=\"kw-chiffre\">3-7 jours</span> · méthadone : après <span class=\"kw-chiffre\">2-4 jours</span>, durée jusqu'à <span class=\"kw-chiffre\">3 semaines</span></td>\n            <td>\n              <strong>Généraux :</strong> tableau pseudo-grippal — <span class=\"kw-clinique\">fièvre</span>, <span class=\"kw-clinique\">frissons</span>, <span class=\"kw-clinique\">myalgies</span>, <span class=\"kw-clinique\">anorexie</span>, <span class=\"kw-clinique\">diarrhée</span>, <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span><br>\n              <strong>Neurovégétatifs :</strong> <span class=\"kw-clinique\">mydriase</span>, bâillements, larmoiement, rhinorrhée, <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-def\">HTA</span>, hypersudation, horripilation<br>\n              <strong>Psychiatriques :</strong> anxiété, irritabilité, insomnie, agitation, <span class=\"kw-clinique\">craving</span>\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">GHB / GBL</span></td>\n            <td><span class=\"kw-chiffre\">1-4 h</span> après la dernière prise ; pic à <span class=\"kw-chiffre\">24 h</span> ; durée ≈ <span class=\"kw-chiffre\">9 jours</span></td>\n            <td>Insomnie, tremblements, <span class=\"kw-clinique\">confusion</span>, <span class=\"kw-clinique\">nausées</span>/<span class=\"kw-clinique\">vomissements</span>, puis <span class=\"kw-clinique\">tachycardie</span>, <span class=\"kw-def\">HTA</span>, agitation, <span class=\"kw-clinique\">convulsions</span>, hallucinations, délirium</td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Piège pupillaire majeur.</strong> Dans le <strong>sevrage aux <span class=\"kw-ttt\">opiacés</span></strong>, la pupille est en <span class=\"kw-clinique\">mydriase</span> — à l'opposé du <span class=\"kw-clinique\">myosis</span> serré de l'intoxication aiguë. La <strong><span class=\"kw-ttt\">kétamine</span></strong> n'entraîne pas de syndrome de sevrage spécifique décrit.</div>","frequence":2},{"id":"78-10","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un usage à risque","contenu":"<p>L'<strong><span class=\"kw-def\">usage à risque</span></strong> est une modalité de <strong>mésusage</strong>. Il correspond à un <strong>niveau de consommation qui expose à des risques de complications</strong>, mais <strong>sans que ces complications soient encore présentes</strong> (et elles ne le seront peut-être jamais). Les complications redoutées sont :</p>\n      <table >\n        <thead><tr><th>Type de risque</th><th>Exemples (Collège)</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Aigu</span><br>(consommation ponctuelle)</td><td><span class=\"kw-alerte\">Syndrome coronarien aigu</span> avec la cocaïne ; <span class=\"kw-alerte\">coma ou décès</span> avec l'héroïne / les <span class=\"kw-ttt\">opioïdes</span> ; accidents ou violences avec l'alcool</td></tr>\n          <tr><td><span class=\"kw-def\">Chronique</span><br>(consommation répétée)</td><td>Complications physiques, psychologiques, sociales ; <strong>passage à la dépendance</strong></td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-warn\"><strong>Notion clé — ce n'est PAS encore un trouble.</strong> L'usage à risque <strong>ne constitue pas un « trouble » médical</strong> (à la différence de l'usage nocif et de la dépendance) : l'<span class=\"kw-def\">OMS</span> le définit comme un <strong><span class=\"kw-def\">état pré-morbide</span></strong>, un <strong><span class=\"kw-def\">facteur de risque</span></strong> survenant <strong>avant l'apparition des premières conséquences</strong>. Son repérage est néanmoins essentiel.</div>\n      <p>Pour les drogues illicites, il n'existe <strong>pas de dose seuil</strong> en dessous de laquelle le risque serait nul : <strong>tout usage de cannabis, cocaïne, amphétamines, <span class=\"kw-ttt\">opiacés</span> ou drogues de synthèse correspond à un mésusage</strong>, donc au minimum à un usage à risque.</p>","frequence":0},{"id":"78-11","rang":"A","rubrique":"Diagnostic positif","titre":"Connaître les modalités du diagnostic d’un usage nocif, d’une dépendance","contenu":"<p>Avec l'<strong>usage à risque</strong> (objectif précédent), l'<strong>usage nocif</strong> et la <strong>dépendance</strong> sont les deux véritables <strong>troubles liés à l'usage</strong> de substance. L'usage nocif n'est pas une addiction, mais ses répercussions en font un « trouble » ; la dépendance constitue le trouble addictif proprement dit.</p>\n      <table >\n        <thead><tr><th>Entité</th><th>Définition</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Usage nocif</span><br>(<span class=\"kw-def\">CIM-10</span>)</td><td>Mode de consommation <strong>préjudiciable à la santé</strong>, entraînant des <strong>dommages avérés</strong> physiques ou psychiques, <strong>sans remplir les critères de dépendance</strong> ; le patient ne fait pas le lien entre dommage et consommation</td></tr>\n          <tr><td><span class=\"kw-def\">Dépendance</span><br>(<span class=\"kw-def\">CIM-10</span>)</td><td>\n            <strong>Dépendance physique :</strong> objectivée par la <span class=\"kw-clinique\">tolérance</span> (besoin d'augmenter les doses) et par le <span class=\"kw-def\">syndrome de sevrage</span> à l'arrêt<br>\n            <strong>Dépendance psychique :</strong> dominée par le <span class=\"kw-clinique\">craving</span> — envie irrépressible de consommer\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Critères de dépendance — <span class=\"kw-def\">CIM-10</span>.</strong> Diagnostic de certitude si <strong>≥ 3 manifestations</strong> présentes <strong>simultanément au cours de la dernière année</strong> :\n        <ul>\n          <li><strong>Craving</strong> : désir puissant ou compulsif d'utiliser la substance ;</li>\n          <li><strong>Perte de contrôle</strong> de l'usage (difficultés à contrôler le début, l'interruption ou le niveau de consommation) ;</li>\n          <li><strong>Syndrome de sevrage</strong> physiologique à l'arrêt ou la réduction (ou réutilisation de la substance pour le soulager) ;</li>\n          <li><strong>Tolérance</strong> : besoin d'une quantité plus importante pour obtenir le même effet ;</li>\n          <li><strong>Abandon des autres intérêts</strong> et sources de plaisir, et temps croissant passé à se procurer/consommer la substance ou à récupérer de ses effets ;</li>\n          <li><strong>Poursuite de la consommation malgré les dommages</strong> manifestement nocifs.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-info\"><strong>Gradation — trouble de l'usage (<span class=\"kw-def\">DSM-5</span>).</strong> Le <span class=\"kw-def\">DSM-5</span> reprend globalement les mêmes critères et <strong>gradue la sévérité</strong> selon leur nombre :\n        <ul>\n          <li><strong>Léger :</strong> <span class=\"kw-chiffre\">2-3</span> critères ;</li>\n          <li><strong>Modéré :</strong> <span class=\"kw-chiffre\">4-5</span> critères ;</li>\n          <li><strong>Sévère :</strong> <span class=\"kw-chiffre\">≥ 6</span> critères.</li>\n        </ul>\n        La <strong>dépendance (<span class=\"kw-def\">CIM-10</span>)</strong> correspond aux troubles de l'usage <strong>modérés à sévères</strong> du <span class=\"kw-def\">DSM-5</span>.\n      </div>","frequence":2},{"id":"78-12","rang":"A","rubrique":"Suivi et/ou pronostic","titre":"Connaître les principales complications","contenu":"<p>Les complications peuvent survenir <strong>dès la première prise</strong> — il n'existe pas de seuil de sécurité. Elles sont psychiatriques et somatiques, et dépendent de la substance comme de la voie d'administration.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Principales complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Cannabis</span></td>\n            <td>\n              <strong>Psychiatriques :</strong> trouble psychotique induit ; troubles anxieux (attaques de panique) ; <span class=\"kw-etio\">épisode dépressif caractérisé</span><br>\n              <strong>Respiratoires :</strong> <span class=\"kw-etio\">BPCO</span>, emphysème ; <span class=\"kw-etio\">pneumothorax</span> ; pneumopathie grave <span class=\"kw-alerte\">EVALI</span><br>\n              <strong>Cardiovasculaires :</strong> <span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">AVC</span> ; maladie de Buerger ; phénomène de Raynaud<br>\n              <strong>Carcinogénicité :</strong> cancers des VADS et broncho-pulmonaires ; tumeurs germinales du testicule<br>\n              <strong>Digestive :</strong> syndrome d'hyperémèse cannabinoïde (<span class=\"kw-clinique\">vomissements</span> incoercibles, <span class=\"kw-clinique\">douleurs abdominales</span>, soulagement par les douches chaudes)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Cocaïne</span></td>\n            <td>\n              <strong>Psychiatriques :</strong> EDC, <span class=\"kw-alerte\">tentatives de suicide</span> ; épisodes délirants induits ; paranoïa<br>\n              <strong>Cardiovasculaires :</strong> <span class=\"kw-alerte\">SCA par vasoconstriction coronaire</span> ; crise hypertensive ; troubles du rythme ; dissection aortique<br>\n              <strong>Pulmonaires :</strong> <span class=\"kw-etio\">pneumothorax</span> ; « crack lung » = <span class=\"kw-alerte\">SDRA</span><br>\n              <strong>Neurologiques :</strong> <span class=\"kw-etio\">AVC</span> <span class=\"kw-etio\">ischémique</span> ou <span class=\"kw-etio\">hémorragique</span> ; <span class=\"kw-clinique\">convulsions</span><br>\n              <strong>ORL</strong> (usage nasal chronique) : ulcération puis <span class=\"kw-alerte\">perforation de la cloison nasale et du palais</span> ; épistaxis ; sinusites<br>\n              <strong>Infectieuses :</strong> IST ; VIH, VHB, VHC ; <span class=\"kw-etio\">endocardite</span><br>\n              <strong>Obstétricales :</strong> <span class=\"kw-alerte\">hématome rétroplacentaire</span> ; fausse couche ; RCIU\n            </td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/78/cocaine-perforation-palais.png\" alt=\"Perforation du palais osseux et lésions dentaires chez un usager chronique de cocaïne par voie nasale\" loading=\"lazy\">\n        <figcaption>Perforation du palais et lésions dentaires liées à l'usage chronique de cocaïne par voie nasale (sniff). Source : fiches sources EDN item 78.</figcaption>\n      </figure>\n      <table >\n        <thead><tr><th>Famille</th><th>Principales complications</th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Amphétamines</span></td>\n            <td>\n              <strong>Psychiatriques :</strong> EDC, tentatives de suicide ; épisodes délirants ; troubles cognitifs<br>\n              <strong>Cardiovasculaires :</strong> <span class=\"kw-etio\">SCA</span> ; urgence hypertensive (dissection aortique) ; troubles du rythme ; <span class=\"kw-etio\">OAP</span> ; cardiomyopathie<br>\n              <strong>Neurologiques :</strong> <span class=\"kw-etio\">AVC</span> ; manifestations extrapyramidales<br>\n              <strong>Autres :</strong> <span class=\"kw-etio\">IRA</span> par rhabdomyolyse ; <span class=\"kw-alerte\">CIVD</span> ; vascularites nécrosantes ; HTAP (méthamphétamine)\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Opiacés</span></td>\n            <td>\n              <strong>Voie IV :</strong> veines sclérosées ; abcès, cellulites, lymphangites ; <span class=\"kw-alerte\">endocardite infectieuse</span> ; VHB, VHC, VIH ; syndrome de Popeye (lymphœdème des mains lié à l'injection détournée de buprénorphine haut dosage)<br>\n              <strong>Voie nasale :</strong> perforation de la cloison nasale ; sinusites<br>\n              <strong>Obstétricales :</strong> syndrome de sevrage néonatal (<span class=\"kw-chiffre\">60 %</span> des nouveau-nés exposés) ; <span class=\"kw-alerte\">mort fœtale in utero</span> en cas de manque ; pas d'effet tératogène<br>\n              <strong>Sociales :</strong> comportements délictueux, prostitution\n            </td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Drogues de synthèse</span></td>\n            <td>Complications infectieuses du « slam » (VIH, hépatites, IST) ; <span class=\"kw-alerte\">syndrome sérotoninergique</span> ; <span class=\"kw-clinique\">convulsions</span>, rhabdomyolyse, <span class=\"kw-etio\">IRA</span> ; cas de décès rapportés</td>\n          </tr>\n        </tbody>\n      </table>\n      <figure class=\"obj-figure\">\n        <img src=\"../assets/images/78/syndrome-popeye-opiaces.png\" alt=\"Lymphœdème bilatéral des mains caractéristique du syndrome de Popeye\" loading=\"lazy\">\n        <figcaption>Syndrome de Popeye : lymphœdème des mains lié à l'injection détournée de buprénorphine haut dosage. Source : fiches sources EDN item 78.</figcaption>\n      </figure>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 339 — Syndrome coronarien aiguë · 340 — <span class=\"kw-etio\">AVC</span> · 152 — <span class=\"kw-etio\">Endocardite</span> infectieuse · 167 — Hépatites virales · 169 — VIH · 162 — IST</em></p>","frequence":1},{"id":"78-13","rang":"B","rubrique":"Examens complémentaires","titre":"Connaître les indications des examens biologiques","contenu":"<p>Les fiches sources évoquent les examens biologiques principalement dans le cadre du dépistage des intoxications et du suivi des traitements de substitution.</p>\n      <table >\n        <thead><tr><th>Indication</th><th>Examen</th></tr></thead>\n        <tbody>\n          <tr><td>Intoxication aiguë</td><td><span class=\"kw-bio\">Dépistage des toxiques associés</span> : <span class=\"kw-ttt\">benzodiazépines</span>, cocaïne, <span class=\"kw-etio\">alcool</span></td></tr>\n          <tr><td>Suivi d'un <span class=\"kw-def\">TSO</span></td><td>\n            <span class=\"kw-bio\">Dosages urinaires</span> : buprénorphine ; métabolites de la méthadone ; <span class=\"kw-ttt\">morphine</span> / <span class=\"kw-ttt\">opiacés</span> — à la primoprescription et aux renouvellements (éviter un surdosage)\n          </td></tr>\n          <tr><td>Primoprescription d'un <span class=\"kw-def\">TSO</span></td><td><span class=\"kw-bio\">Test de grossesse</span> chez la femme en âge de procréer, répété (risque d'aménorrhée)</td></tr>\n          <tr><td>Primoprescription de méthadone</td><td><span class=\"kw-bio\">ECG</span> : recherche d'un allongement du <strong>QT</strong> et d'un trouble du rythme ventriculaire (risque de mort subite), puis périodiquement</td></tr>\n          <tr><td>Sevrage aux <span class=\"kw-ttt\">opiacés</span></td><td>La biologie peut montrer : hémoconcentration ; hyperleucocytose ; <span class=\"kw-bio\">hyperglycémie</span></td></tr>\n          <tr><td>Usage par voie injectable ou nasale</td><td>\n            <span class=\"kw-bio\">Sérologies VHB, VHC et VIH</span> : dépistage des comorbidités infectieuses transmises par l'<strong>injection</strong> (slam, shoot) et le <strong>partage de matériel</strong> (y compris pailles de sniff) — chez les usagers de drogue par voie veineuse en France, le VIH atteint ≈ <span class=\"kw-chiffre\">10 %</span> et le VHC ≈ <span class=\"kw-chiffre\">30 %</span><br>\n            Intègre le <span class=\"kw-bio\">bilan infectieux</span> du surdosage aux <span class=\"kw-ttt\">opiacés</span> (<span class=\"kw-imagerie\">radiographie thoracique</span>, <span class=\"kw-bio\">hémocultures</span>, prélèvements cutanés aux points d'injection, <span class=\"kw-bio\">ECBU</span>, <span class=\"kw-bio\">sérologies</span> VHB/VHC/VIH ± <span class=\"kw-ttt\">vaccination antitétanique</span>)\n          </td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>À retenir.</strong> Les <strong><span class=\"kw-bio\">sérologies</span> VHB, VHC, VIH</strong> font partie du bilan systématique de tout usager exposé par <strong>voie injectable</strong> ou par <strong>partage de matériel nasal</strong>, au titre du dépistage des comorbidités infectieuses (cf. complications infectieuses des <span class=\"kw-ttt\">opiacés</span> IV, de la cocaïne et des amphétamines).</div>","frequence":0},{"id":"78-14","rang":"A","rubrique":"Prise en charge","titre":"Connaître les principes généraux de la prise en charge","contenu":"<p>La prise en charge d'une addiction est <strong>globale et multimodale</strong> : elle associe une réponse <span class=\"kw-def\">médicale</span>, <span class=\"kw-def\">psychosociale</span> et <span class=\"kw-def\">communautaire</span>. Elle s'appuie sur l'<strong>alliance thérapeutique</strong> et les <strong>entretiens motivationnels</strong>.</p>\n      <p>Elle peut viser autant l'<strong>arrêt</strong> de la consommation que la simple <strong>réduction des consommations et des dommages</strong> — l'objectif est négocié avec le patient.</p>\n      <p><strong><span class=\"kw-def\">Réduction des risques et des dommages (RDRD).</span></strong> Stratégie visant à réduire les risques sanitaires liés à l'usage de substances et aux pratiques sexuelles associées, sans exiger l'arrêt de la consommation.</p>\n      <table >\n        <thead><tr><th>Volet</th><th>Contenu</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Acteurs</span></td><td>\n            <strong><span class=\"kw-def\">CAARUD</span> :</strong> centres d'accueil et d'accompagnement à la réduction des risques pour usagers de drogues<br>\n            <strong><span class=\"kw-def\">CSAPA</span> :</strong> centres de soins, d'accompagnement et de prévention en addictologie\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Mesures</span></td><td>\n            Accueil sans condition, quelle que soit la situation de l'usager<br>\n            Information sur les risques et leur prévention<br>\n            Distribution de matériel de prévention : seringues, préservatifs, kits crack<br>\n            Salles de consommation à moindre risque ; récupération du matériel usagé<br>\n            Accès aux droits et aux soins ; orientation vers les dispositifs spécialisés ; groupes d'entraide\n          </td></tr>\n        </tbody>\n      </table>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques · 74 — Psychotropes</em></p>","frequence":1},{"id":"78-15","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de l’intoxication aiguë","contenu":"<p>Le traitement de l'intoxication aiguë est avant tout <strong>symptomatique</strong> ; seuls les <span class=\"kw-ttt\">opiacés</span> disposent d'un <strong>antidote spécifique</strong>.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Traitement de l'intoxication aiguë</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cannabis</span></td><td>\n            Symptomatique : <span class=\"kw-ttt\">antipsychotiques</span> si symptômes psychotiques ; <span class=\"kw-ttt\">anxiolytiques</span> si angoisse ou agitation — <strong>hydroxyzine</strong> en 1ʳᵉ intention, <span class=\"kw-ci\">éviter les benzodiazépines</span>\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Cocaïne</span></td><td><span class=\"kw-alerte\">Aucun antidote spécifique</span> du surdosage → traitement symptomatique</td></tr>\n          <tr><td><span class=\"kw-def\">Amphétamines</span></td><td>Symptomatique ; si <span class=\"kw-clinique\">hyperthermie</span> d'origine sérotoninergique → <span class=\"kw-ttt\">cyproheptadine</span></td></tr>\n          <tr><td><span class=\"kw-def\">Opiacés</span></td><td>Antidote spécifique = <span class=\"kw-ttt\">naloxone</span> (voir encadré ci-dessous)</td></tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Naloxone (Narcan®) — antidote du surdosage aux <span class=\"kw-ttt\">opiacés</span>.</strong>\n        <ul>\n          <li><strong>Mécanisme :</strong> antagoniste des récepteurs morphiniques ; aucune <span class=\"kw-ci\">contre-indication</span>.</li>\n          <li><strong>Voies :</strong> IV (titration), mais aussi <strong>spray nasal</strong> et IM — utilisables par l'entourage et les secouristes.</li>\n          <li><strong>Titration IV :</strong> <span class=\"kw-chiffre\">0,04-0,08 mg</span> toutes les <span class=\"kw-chiffre\">2 min</span>, jusqu'à <span class=\"kw-chiffre\">2 mg</span> maximum.</li>\n          <li><strong>Objectif :</strong> restaurer une FR ≥ <span class=\"kw-chiffre\">15/min</span> — <span class=\"kw-alerte\">et non l'éveil complet</span>, pour ne pas déclencher un syndrome de sevrage.</li>\n          <li><strong>Surveillance :</strong> durée d'action plus courte que celle des <span class=\"kw-ttt\">opioïdes</span> → surveillance prolongée et relais en perfusion sur <span class=\"kw-chiffre\">4 h</span>.</li>\n          <li><strong>Échec :</strong> doit faire reconsidérer le diagnostic d'intoxication isolée aux <span class=\"kw-ttt\">opioïdes</span>.</li>\n        </ul>\n        Mesures associées : oxygénothérapie, ventilation assistée, dépistage des toxiques associés.\n      </div>","frequence":0},{"id":"78-16","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement du syndrome de sevrage","contenu":"<p>Le traitement du syndrome de sevrage est essentiellement <strong>symptomatique</strong>, en évitant les <span class=\"kw-ttt\">benzodiazépines</span>.</p>\n      <table >\n        <thead><tr><th>Famille</th><th>Traitement du syndrome de sevrage</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Cannabis</span></td><td>Symptomatique ; <span class=\"kw-ttt\">hydroxyzine</span> en 1ʳᵉ intention si angoisse ou agitation, <span class=\"kw-ci\">éviter les BZD</span></td></tr>\n          <tr><td><span class=\"kw-def\">Cocaïne</span></td><td>Traitement symptomatique ; entretiens motivationnels ; <span class=\"kw-ci\">éviter les BZD</span></td></tr>\n          <tr><td><span class=\"kw-def\">Opiacés</span></td><td>\n            <strong>Traitement de substitution opiacée</strong> (méthadone ou buprénorphine haut dosage)<br>\n            <strong>Symptomatique adapté :</strong> antalgiques non <span class=\"kw-ttt\">opiacés</span> ; antispasmodiques ; antiémétiques ; antidiarrhéiques ; anxiolytiques non-BZD (<span class=\"kw-ttt\">cyamémazine</span> ou <span class=\"kw-ttt\">hydroxyzine</span>)<br>\n            <strong>Prévention :</strong> diminution progressive des doses\n          </td></tr>\n        </tbody>\n      </table>","frequence":0},{"id":"78-17","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités du traitement de la dépendance","contenu":"<p>Le traitement de la dépendance dépend de la substance : seuls les <span class=\"kw-ttt\">opiacés</span> disposent d'un traitement de substitution.</p>\n      <table >\n        <thead><tr><th>Situation</th><th>Traitement de la dépendance</th></tr></thead>\n        <tbody>\n          <tr><td><span class=\"kw-def\">Dépendance aux opiacés</span></td><td>\n            <strong>Traitement de substitution opiacée (<span class=\"kw-def\">TSO</span>)</strong> = traitement de choix : méthadone ; buprénorphine haut dosage (<span class=\"kw-ttt\">Subutex</span>®) ; association buprénorphine-naloxone (<span class=\"kw-ttt\">Suboxone</span>®) — <span class=\"kw-ci\">sans les associer entre eux</span><br>\n            Durée : quelques mois, quelques années ou à vie selon le degré de dépendance\n          </td></tr>\n          <tr><td><span class=\"kw-def\">Autres substances</span><br>(cannabis, cocaïne, amphétamines, hallucinogènes, GHB, <span class=\"kw-ttt\">kétamine</span>)</td><td>\n            <span class=\"kw-alerte\">Pas de traitement de substitution</span><br>\n            Prise en charge <strong>multimodale</strong> : traitement symptomatique + <span class=\"kw-def\">thérapie cognitivo-comportementale</span>, associée à la réduction des risques et des dommages\n          </td></tr>\n        </tbody>\n      </table>\n      <p>Les modalités précises de prescription du <span class=\"kw-def\">TSO</span> sont détaillées dans l'objectif suivant.</p>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 73 — Techniques psychothérapeutiques</em></p>","frequence":0},{"id":"78-18","rang":"B","rubrique":"Prise en charge","titre":"Connaître les modalités de la prescription d’un traitement substitutif aux opiacés (TSO)","contenu":"<p>Le <strong><span class=\"kw-def\">traitement de substitution aux opiacés (TSO)</span></strong> repose sur trois molécules, encadrées par des règles de prescription strictes.</p>\n      <table >\n        <thead><tr><th>Critère</th><th>Chlorhydrate de méthadone</th><th>Buprénorphine haut dosage (BHD)</th><th>BHD + <span class=\"kw-ttt\">naloxone</span></th></tr></thead>\n        <tbody>\n          <tr>\n            <td><span class=\"kw-def\">Mécanisme</span></td>\n            <td><span class=\"kw-ttt\">Agoniste</span> des récepteurs aux <span class=\"kw-ttt\">opiacés</span></td>\n            <td>Agoniste <strong>partiel</strong> des récepteurs aux <span class=\"kw-ttt\">opiacés</span></td>\n            <td>Agoniste + antagoniste des récepteurs aux <span class=\"kw-ttt\">opiacés</span></td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Formes</span></td>\n            <td>Sirop (initiation) puis gélule (relais chez les patients traités depuis ≥ <span class=\"kw-chiffre\">1 an</span> et stabilisés)</td>\n            <td>Comprimés sublinguaux</td>\n            <td>Comprimés sublinguaux</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Prescripteur</span></td>\n            <td>Sirop : initiation en établissement de santé ou centre spécialisé, puis relais en ville. Gélule : prescription initiale semestrielle réservée aux <strong><span class=\"kw-def\">CSAPA</span></strong> ou services spécialisés</td>\n            <td>Tout médecin</td>\n            <td>Tout médecin</td>\n          </tr>\n          <tr>\n            <td><span class=\"kw-def\">Durée maximale</span></td>\n            <td>Sirop <span class=\"kw-chiffre\">14 jours</span> ; gélule <span class=\"kw-chiffre\">28 jours</span></td>\n            <td><span class=\"kw-chiffre\">28 jours</span></td>\n            <td><span class=\"kw-chiffre\">28 jours</span></td>\n          </tr>\n        </tbody>\n      </table>\n      <div class=\"callout callout-info\"><strong>Règles communes de prescription.</strong>\n        <ul>\n          <li><strong>Ordonnance sécurisée</strong> avec mention obligatoire du nom du pharmacien.</li>\n          <li><strong>Délivrance fractionnée</strong> par périodes de <span class=\"kw-chiffre\">7 jours</span>, sauf mention expresse « délivrance en une seule fois ».</li>\n          <li><strong>Initiation de la méthadone :</strong> 1ʳᵉ prise <span class=\"kw-chiffre\">10 h</span> après la dernière consommation d'opioïde ; posologie initiale ≤ <span class=\"kw-chiffre\">60 mg/j</span> ; augmentation ≤ <span class=\"kw-chiffre\">10 mg/semaine</span>.</li>\n          <li><strong>Bonnes pratiques :</strong> test de grossesse ; dosages urinaires ; <span class=\"kw-bio\">ECG</span> (QT) avant la méthadone.</li>\n        </ul>\n      </div>\n      <div class=\"callout callout-warn\"><strong>Piège.</strong> Méthadone et buprénorphine ne s'associent <span class=\"kw-ci\">jamais</span>. Le risque d'<strong>usage détourné</strong> du <span class=\"kw-def\">TSO</span> concerne environ 1 cas sur 3 — d'où le contrôle de la délivrance et les dosages urinaires.</div>\n      <p class=\"obj-renvois\"><em>📎 Items liés : 74 — Psychotropes</em></p>","frequence":1,"liens":[{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/opiaces","label":"Pharmacomedicale — Opiacés"}]}],"astuces":[],"strategie":{"urgence":"<p><strong>Overdose aux <span class=\"kw-ttt\">opiacés</span> :</strong> urgence vitale immédiate — la <span class=\"kw-alerte\">dépression respiratoire</span> (<span class=\"kw-clinique\">bradypnée ≤ 10/min</span>) peut évoluer vers un <span class=\"kw-alerte\">arrêt cardio-respiratoire hypoxique</span> ; administrer la <span class=\"kw-ttt\">naloxone</span> sans délai.<br><strong>Délai du sevrage opiacé :</strong> apparition <span class=\"kw-chiffre\">6-12 h</span> après la dernière prise pour l'héroïne, <span class=\"kw-chiffre\">2-4 jours</span> pour la méthadone.<br><strong>Intoxication aux stimulants :</strong> guetter d'emblée l'<span class=\"kw-alerte\">hyperthermie maligne = syndrome sérotoninergique</span> (amphétamines) et le <span class=\"kw-etio\">syndrome coronarien aigu</span> (cocaïne).</p>","hospit":"<p><strong>Urgences / réanimation :</strong> toute <span class=\"kw-alerte\">overdose d'opiacés</span> ou intoxication grave — <span class=\"kw-ttt\">oxygénothérapie</span>, ventilation assistée et <span class=\"kw-clinique\">surveillance cardiorespiratoire</span> prolongée.<br><strong>Addictologie spécialisée :</strong> orientation vers un <span class=\"kw-def\">CSAPA</span> (soins, accompagnement et prévention en addictologie) et un <span class=\"kw-def\">CAARUD</span> (réduction des risques).<br><strong>Initiation d'un TSO :</strong> la <span class=\"kw-ttt\">méthadone</span> (forme sirop) est initiée en <span class=\"kw-def\">établissement de santé</span> ou en <span class=\"kw-def\">centre spécialisé</span>, avec relais possible en médecine de ville.</p>","redflags":"<ul><li><strong>Toxidrome morphinique :</strong> <span class=\"kw-clinique\">coma calme</span> hypotonique aréflexique, <span class=\"kw-clinique\">myosis serré bilatéral</span>, <span class=\"kw-clinique\">bradypnée ≤ 10/min</span> ou respiration de Cheyne-Stokes → <span class=\"kw-alerte\">arrêt respiratoire</span></li><li><strong>Amphétamines :</strong> <span class=\"kw-alerte\">hyperthermie maligne = syndrome sérotoninergique</span> (signe de gravité extrême)</li><li><strong>Cocaïne / amphétamines :</strong> <span class=\"kw-etio\">syndrome coronarien aigu</span> (<span class=\"kw-alerte\">IDM</span> par vasoconstriction coronaire), <span class=\"kw-etio\">crise hypertensive</span>, <span class=\"kw-etio\">dissection aortique</span>, <span class=\"kw-etio\">AVC</span>, <span class=\"kw-clinique\">convulsions</span></li><li><strong>Crack / cocaïne inhalée :</strong> <span class=\"kw-etio\">SDRA</span> (crack lung), pneumothorax</li><li><strong>GHB/GBL :</strong> overdose « <span class=\"kw-alerte\">G-Hole</span> » (<span class=\"kw-clinique\">bradypnée</span>, apnée) ; <span class=\"kw-clinique\">convulsions</span> et délirium possibles au sevrage</li><li><strong>Sevrage aux amphétamines :</strong> dépression avec anhédonie → <span class=\"kw-alerte\">risque suicidaire</span></li></ul>","principes":"<p>La conduite dépend de la situation clinique et de la substance ; en dehors de l'urgence, elle est addictologique et au long cours.</p><p><strong>Overdose aux <span class=\"kw-ttt\">opiacés</span> — antidote</strong></p><p>Urgence vitale</p><ul><li><strong>Antidote :</strong> <span class=\"kw-ttt\">naloxone</span> (Narcan®), antagoniste des récepteurs morphiniques, en <span class=\"kw-ttt\">IV</span>, <span class=\"kw-ttt\">IM</span> ou spray nasal</li><li><strong>Titration IV :</strong> <span class=\"kw-chiffre\">0,04-0,08 mg</span> toutes les <span class=\"kw-chiffre\">2 min</span> jusqu'à <span class=\"kw-chiffre\">2 mg</span> maximum ; objectif <span class=\"kw-clinique\">FR ≥ 15/min</span> et non le réveil complet</li><li><strong>Mesures associées :</strong> arrêt de l'opioïde, stimulation du patient, <span class=\"kw-ttt\">ventilation au masque + O₂</span> si pauses ou apnées (R3)</li><li><strong>Échec de la <span class=\"kw-ttt\">naloxone</span> :</strong> revoir le diagnostic d'intoxication isolée aux <span class=\"kw-ttt\">opioïdes</span></li></ul><p><strong>Intoxication aux stimulants (cocaïne, amphétamines)</strong></p><p>Symptomatique</p><ul><li><strong>Aucun antidote spécifique :</strong> prise en charge <span class=\"kw-ttt\">symptomatique</span> et surveillance</li><li><strong>Hyperthermie sérotoninergique (amphétamines) :</strong> administration de <span class=\"kw-ttt\">cyproheptadine</span></li></ul><p><strong>Intoxication cannabis / hallucinogènes</strong></p><p>Symptomatique</p><ul><li><strong>Traitement uniquement symptomatique</strong></li><li><strong>Symptômes psychotiques :</strong> <span class=\"kw-ttt\">antipsychotiques</span></li><li><strong>Angoisse / agitation :</strong> <span class=\"kw-ttt\">hydroxyzine</span> en 1ʳᵉ intention, <span class=\"kw-ci\">éviter les benzodiazépines</span></li></ul><p><strong>Syndrome de sevrage</strong></p><p>Sevrage</p><ul><li><strong>Opiacés :</strong> <span class=\"kw-ttt\">traitement de substitution</span> (méthadone, buprénorphine) + symptomatique (<span class=\"kw-ttt\">antalgiques non opiacés</span>, antispasmodiques, antiémétiques, antidiarrhéiques, anxiolytiques non BZD)</li><li><strong>Prévention :</strong> diminution progressive des doses</li><li><strong>Cocaïne / amphétamines / cannabis :</strong> traitement <span class=\"kw-ttt\">symptomatique</span> + entretiens motivationnels, <span class=\"kw-ci\">éviter les benzodiazépines</span></li></ul><p><strong>Dépendance — prise en charge au long cours</strong></p><p>Au long cours</p><ul><li><strong>Opiacés :</strong> <span class=\"kw-ttt\">traitement de substitution aux opiacés (TSO)</span> = traitement de choix — méthadone, buprénorphine haut dosage (Subutex®) ou BHD-naloxone (Suboxone®), sans les associer</li><li><strong>Autres substances :</strong> pas de TSO → prise en charge <span class=\"kw-ttt\">multimodale</span> (symptomatique + <span class=\"kw-ttt\">thérapie cognitivo-comportementale</span>)</li><li><strong>Réduction des risques (RDRD) :</strong> <span class=\"kw-def\">CAARUD</span> / <span class=\"kw-def\">CSAPA</span>, matériel stérile, salles de consommation à moindre risque</li></ul>","suivi":"<p><strong>Après <span class=\"kw-ttt\">naloxone</span> :</strong> <span class=\"kw-clinique\">surveillance prolongée</span> (toutes les heures) car sa durée d'action est plus courte que celle des <span class=\"kw-ttt\">opioïdes</span> → risque de re-sédation et réinjections, voire <span class=\"kw-ttt\">perfusion sur 4 h</span>.<br><strong>Méthadone :</strong> <span class=\"kw-bio\">ECG</span> à la recherche d'un allongement du <span class=\"kw-bio\">QT</span> à la primoprescription puis périodique, <span class=\"kw-bio\">dosages urinaires</span> et test de grossesse chez la femme en âge de procréer.<br><strong>Cadre du TSO :</strong> prescription sécurisée, délivrance <span class=\"kw-chiffre\">fractionnée par 7 jours</span> ; durée maximale <span class=\"kw-chiffre\">14 jours</span> (méthadone sirop) à <span class=\"kw-chiffre\">28 jours</span> (gélule ou buprénorphine).</p>"},"liensGlobaux":[{"href":"https://pharmacomedicale.org/medicaments/par-specialites/category/opiaces","label":"pharmacomedicale.org"}],"arbre":{"rootId":"root","nodes":[{"id":"root","kind":"root","label":"Usager de substance psychoactive — Quelle situation clinique ?","detail":"<h4>Conduite à tenir devant un usage de drogues — Intoxication aiguë, syndrome de sevrage et dépendance</h4>","branches":[{"to":"q_intox","label":"Intoxication aiguë / overdose","color":"red"},{"to":"q_sevrage","label":"Syndrome de sevrage","color":"blue"},{"to":"t_dependance","label":"Dépendance installée","color":"green"}]},{"id":"q_intox","kind":"decision","label":"Intoxication aiguë / overdose — Quel toxidrome domine ?","branches":[{"to":"t_opiaces","label":"Coma calme + myosis + bradypnée","color":"red"},{"to":"t_stimulants","label":"Agitation, tachycardie, HTA, mydriase","color":"amber"},{"to":"t_perturbateurs","label":"Hallucinations / angoisse / sédation","color":"amber"}]},{"id":"t_opiaces","kind":"terminal","label":"Overdose aux opiacés → NALOXONE — Urgence vitale","color":"red","detail":"<h4>Reconnaître</h4><ul><li><span class=\"kw-clinique\">Coma calme</span> hypotonique aréflexique</li><li><span class=\"kw-clinique\">Myosis serré bilatéral</span></li><li><span class=\"kw-clinique\">Bradypnée ≤ 10/min</span> / Cheyne-Stokes → <span class=\"kw-alerte\">ACR hypoxique</span></li></ul><h4>Antidote</h4><ul><li><span class=\"kw-ttt\">Naloxone</span> en IV / IM / spray nasal</li><li>Titration <span class=\"kw-chiffre\">0,04-0,08 mg / 2 min</span> jusqu'à <span class=\"kw-chiffre\">2 mg</span> max</li><li>Objectif <span class=\"kw-clinique\">FR ≥ 15/min</span>, pas le réveil complet</li></ul><h4>Mesures associées</h4><ul><li>Arrêt de l'opioïde + stimulation</li><li><span class=\"kw-ttt\">Ventilation au masque + O₂</span> si apnées</li><li>Surveillance prolongée (durée < opioïdes)</li></ul>"},{"id":"t_stimulants","kind":"terminal","label":"Intoxication aux stimulants (cocaïne, amphétamines) — Symptomatique + surveillance","color":"amber","detail":"<h4>Tableau</h4><ul><li><span class=\"kw-clinique\">Tachycardie</span>, <span class=\"kw-clinique\">HTA</span>, <span class=\"kw-clinique\">mydriase</span>, agitation</li></ul><h4>Conduite</h4><ul><li><span class=\"kw-alerte\">Aucun antidote spécifique</span> → <span class=\"kw-ttt\">symptomatique</span></li><li>Hyperthermie sérotoninergique → <span class=\"kw-ttt\">cyproheptadine</span></li></ul><h4>Red flags</h4><ul><li><span class=\"kw-etio\">SCA</span>, <span class=\"kw-etio\">AVC</span>, <span class=\"kw-etio\">crise hypertensive</span>, <span class=\"kw-clinique\">convulsions</span></li></ul>"},{"id":"t_perturbateurs","kind":"terminal","label":"Intoxication cannabis / hallucinogènes — Traitement symptomatique","color":"amber","detail":"<h4>Tableau</h4><ul><li>Cannabis : ivresse cannabique ; hallucinogènes : <span class=\"kw-clinique\">hallucinations</span>, angoisse</li></ul><h4>Conduite</h4><ul><li>Traitement <span class=\"kw-ttt\">symptomatique</span></li><li>Angoisse / agitation → <span class=\"kw-ttt\">hydroxyzine</span>, <span class=\"kw-ci\">éviter les BZD</span></li><li>Symptômes psychotiques → <span class=\"kw-ttt\">antipsychotiques</span></li></ul>"},{"id":"q_sevrage","kind":"decision","label":"Syndrome de sevrage — De quelle substance ?","branches":[{"to":"t_sevrage_opiaces","label":"Opiacés","color":"blue"},{"to":"t_sevrage_autres","label":"Cocaïne / amphétamines / cannabis","color":"blue"}]},{"id":"t_sevrage_opiaces","kind":"terminal","label":"Sevrage aux opiacés → TSO — Substitution + symptomatique","color":"blue","detail":"<h4>Délais</h4><ul><li>Héroïne <span class=\"kw-chiffre\">6-12 h</span> (durée <span class=\"kw-chiffre\">3-7 j</span>) ; méthadone <span class=\"kw-chiffre\">2-4 j</span> (durée jusqu'à <span class=\"kw-chiffre\">3 sem</span>)</li></ul><h4>Traitement</h4><ul><li><span class=\"kw-ttt\">TSO</span> (méthadone / buprénorphine)</li><li>Symptomatique : <span class=\"kw-ttt\">antalgiques non opiacés</span>, antiémétiques, antidiarrhéiques, anxiolytiques non BZD</li><li>Prévention : décroissance progressive des doses</li></ul>"},{"id":"t_sevrage_autres","kind":"terminal","label":"Sevrage cocaïne / amphétamines / cannabis — Symptomatique","color":"blue","detail":"<h4>Conduite</h4><ul><li>Traitement <span class=\"kw-ttt\">symptomatique</span> + entretiens motivationnels</li><li><span class=\"kw-ci\">Éviter les benzodiazépines</span></li><li>Sevrage amphétamines → guetter le <span class=\"kw-alerte\">risque suicidaire</span></li></ul>"},{"id":"t_dependance","kind":"terminal","label":"Dépendance → PEC addictologique au long cours — Hors urgence","color":"green","detail":"<h4>Opiacés</h4><ul><li><span class=\"kw-ttt\">TSO</span> = traitement de choix (méthadone, BHD)</li><li>Cadre : <span class=\"kw-bio\">dosages urinaires</span>, délivrance fractionnée</li></ul><h4>Autres substances</h4><ul><li>Pas de TSO → PEC <span class=\"kw-ttt\">multimodale</span></li><li><span class=\"kw-ttt\">TCC</span> + entretien motivationnel</li></ul><h4>Réduction des risques</h4><ul><li><span class=\"kw-def\">CAARUD</span> / <span class=\"kw-def\">CSAPA</span>, matériel stérile</li></ul>"}]},"cards":[{"i":"06d2ae358094","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Quelle est la définition et les différents types d'opiacés ?","a":"<p>Les opiacés sont des substances dérivées du <strong>pavot</strong>. On distingue :</p><ul><li>Les opiacés naturels comme la <strong>morphine</strong>.</li><li>Les opiacés semi-synthétiques comme l'<strong>héroïne</strong>.</li><li>Les opiacés de synthèse à action morphinique.</li></ul>"},{"i":"58207150c1ef","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Que sont les drogues de synthèse (NPS/NSP) ?","a":"<p>Les drogues de synthèse, ou <strong>Nouveaux Produits de Synthèse (NPS / NSP)</strong>, sont des substances récentes fabriquées principalement en Asie et en Europe, longtemps non contrôlées ni réglementées.</p>"},{"i":"60962fac051c","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Que sont les amphétamines et quels sont leurs principaux représentants ?","a":"<p>Les amphétamines sont des <strong>dérivés amphétaminiques de synthèse</strong>. Les principaux représentants incluent l'amphétamine, le <strong>MDMA/ecstasy</strong> et la <strong>méthamphétamine</strong>.</p>"},{"i":"7bf42ae964e9","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Quelle est la définition et les caractéristiques principales du cannabis ?","a":"<p>Le cannabis est une substance issue de la plante <strong>Cannabis sativa</strong>. C'est la substance illicite la plus consommée en France.</p>"},{"i":"90299b4815a0","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Quelle est la définition et l'origine de la cocaïne ?","a":"<p>La cocaïne est une substance <strong>stimulante</strong> extraite des feuilles de <strong>coca</strong>, principalement cultivées en Amérique du Sud.</p>"},{"i":"ab311acb770e","n":78,"o":"78-1","u":"Définition","t":"Connaître la définition de l’addiction au cannabis, à la cocaïne, aux amphétamines, aux opiacés, aux drogues de synthèse","q":"Comment est défini le mésusage pour les substances illicites mentionnées ?","a":"<p>Pour les substances illicites, <strong>tout usage est considéré comme un mésusage</strong>. Cela peut être :</p><ul><li>Un <strong>usage à risque</strong>, même en l'absence de trouble addictologique constitué.</li><li>Une <strong>dépendance</strong>.</li></ul><p>Il n'existe par ailleurs <strong>pas de dose seuil connue</strong> en dessous de laquelle le risque serait nul.</p>"},{"i":"0cb8e2b31b49","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quelles sont les différentes formes du principe actif de la cocaïne ?","a":"<p>Le principe actif de la cocaïne se présente sous deux formes principales :</p><ul><li>Le <strong>chlorhydrate de cocaïne</strong> : c'est la <strong>poudre blanche</strong>.</li><li>La <strong>cocaïne base</strong> : on distingue le <strong>crack</strong> (obtenu par adjonction de bicarbonate de soude) et la <strong>free base</strong> (obtenue avec de l'ammoniaque).</li></ul>"},{"i":"25a8315a171f","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quels sont les différents types d'opiacés classés selon leur origine et citez un exemple pour chaque type ?","a":"<p>On distingue trois types d'opiacés selon leur origine :</p><ul><li>Les <strong>opiacés naturels</strong>, comme la <strong>morphine</strong>.</li><li>Les <strong>opiacés semi-synthétiques</strong>, comme l'<strong>héroïne (diacétylmorphine)</strong>.</li><li>Les <strong>opiacés synthétiques à action morphinique</strong>, tels que le <strong>tramadol</strong>, la <strong>codéine</strong>, la <strong>buprénorphine</strong>, la <strong>méthadone</strong>, l'<strong>oxycodone</strong> ou le <strong>fentanyl</strong>.</li></ul>"},{"i":"7abaca689921","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quel est le principe psychoactif du cannabis, sa classe et ses récepteurs cibles ?","a":"<p>Le principal principe psychoactif du cannabis est le <strong>Δ9-THC (delta-9-tétrahydrocannabinol)</strong>. C'est un <strong>agoniste des récepteurs cannabinoïdes CB1 et CB2</strong>.</p>"},{"i":"aef14789c09f","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Citez des exemples de drogues de synthèse dont le principe actif est de type cannabinoïde ou cathinone.","a":"<p>Les drogues de synthèse incluent :</p><ul><li>Les <strong>cannabinoïdes de synthèse</strong> (ex : <strong>Spice</strong>) avec un effet hallucinogène.</li><li>Les <strong>cathinones de synthèse</strong> (ex : <strong>méphédrone</strong>, <strong>MDPV</strong>, <strong>méthylone</strong>, <strong>3-MMC</strong>, <strong>4-MEC</strong>) avec un effet psychostimulant.</li></ul>"},{"i":"ccf6a4e5ec54","n":78,"o":"78-2","u":"Définition","t":"Connaître les principes actifs","q":"Quels sont les principaux principes actifs des amphétamines et de leurs dérivés ?","a":"<p>Les principaux principes actifs de cette famille incluent :</p><ul><li>L'<strong>amphétamine</strong>.</li><li>La <strong>MDMA (ecstasy)</strong>.</li><li>La <strong>méthamphétamine</strong>, qui présente des effets particulièrement puissants et un fort potentiel addictif.</li></ul>"}]};